    'Leo Audio Gaming': 'Leo Audio Gaming',
    '📖 Bestiary': '📖 Bestiário',
    '🪙 Coin Shop': '🪙 Loja de Moedas',
    '⌨️ Command Center': '⌨️ Centro de Comando',
    '👑 Boss Rush': '👑 Assalto de Chefes',
    '📚 Chronicles': '📚 Crônicas',
    '📋 Bounty Board': '📋 Quadro de Recompensas',
    '🏛️ Hall of Records': '🏛️ Salão dos Registros',
    '🎃 Events': '🎃 Eventos',
